<script setup lang="ts">
import { Plus, ArrowUpRight, Copy, Trash2, FileUp, FileText, Search, MoreHorizontal } from 'lucide-vue-next'
import type { Article, Resource } from '@qinbian/shared'
const ctx=useQinbian(),items=ref<Article[]>([]),templates=ref<Resource[]>([]),query=ref(''),creating=ref(false),title=ref(''),templateId=ref(''),fileInput=ref<HTMLInputElement>(),importing=ref(false)
const filtered=computed(()=>items.value.filter(d=>d.title.toLowerCase().includes(query.value.toLowerCase())))
async function refresh(){items.value=await apiFetch('/api/documents')};onMounted(async()=>{try{await refresh();templates.value=await apiFetch('/api/resources',{query:{kind:'template'}})}catch(e){ctx.error(e)}})
async function create(){try{const d=await apiFetch<Article>('/api/documents',{method:'POST',body:templateId.value?{title:title.value||undefined,resourceId:templateId.value}:{title:title.value||'未命名文章',themeSetId:'mine',blocks:[]}});navigateTo('/documents/'+d.id)}catch(e){ctx.error(e)}}
async function clone(d:Article){try{await apiFetch('/api/documents/'+d.id+'/clone',{method:'POST'});await refresh();ctx.notify('已另存一份文章')}catch(e){ctx.error(e)}}
async function remove(d:Article){if(!confirm(`将“${d.title}”移到回收站？`))return;try{await apiFetch('/api/documents/'+d.id,{method:'DELETE'});await refresh()}catch(e){ctx.error(e)}}
async function importDraft(files:FileList|null){const file=files?.[0];if(!file)return;if(file.size>100*1024*1024){ctx.notify('草稿文件请控制在100 MB以内',true);return}importing.value=true;try{const raw=JSON.parse(await file.text());const d=await apiFetch<Article>('/api/documents/import',{method:'POST',body:{...raw,title:file.name.replace(/\.json$/,'')}});ctx.notify('旧草稿已导入');navigateTo('/documents/'+d.id)}catch(e){ctx.error(e)}finally{importing.value=false;if(fileInput.value)fileInput.value.value=''}}
</script>
<template><div class="page"><header class="page-heading"><div><p class="eyebrow">落笔成文 · 妥帖收藏</p><h1>我的文章<span class="title-dot">。</span></h1><p class="page-description">每一次写作，都有自己的起承转合。</p></div><div class="heading-actions"><button class="btn" :disabled="importing" @click="fileInput?.click()"><FileUp :size="16"/>{{importing?'正在导入…':'导入旧草稿'}}</button><button class="btn primary" @click="creating=true"><Plus :size="16"/>新建文章</button><input ref="fileInput" type="file" hidden accept="application/json,.json" @change="importDraft(($event.target as HTMLInputElement).files)"></div></header><div class="list-toolbar"><span class="muted small">共 {{items.length}} 篇稿件</span><label class="search-field"><Search :size="16"/><input v-model="query" placeholder="按文章名称寻找" aria-label="搜索文章"></label></div><div v-if="!filtered.length" class="empty-state"><FileText :size="34"/><h3>下一篇，写什么呢</h3><p>从一张白纸开始，也可以挑选熟悉的编排模板。</p><button class="btn" @click="creating=true">开始写作</button></div><div class="document-list"><article v-for="(d,i) in filtered" :key="d.id"><span class="document-number">{{String(i+1).padStart(2,'0')}}</span><NuxtLink :to="'/documents/'+d.id" class="document-list-title"><h2>{{d.title}}</h2><p>{{d.blocks.length}} 枚组件<span>·</span>{{ctx.themes.value.find(t=>t.id===d.themeSetId)?.name||'我的资源'}}<span>·</span>{{formatDate(d.updatedAt)}}</p></NuxtLink><button class="icon-button" :aria-label="'复制文章 '+d.title" @click="clone(d)"><Copy :size="16"/></button><button class="icon-button" :aria-label="'删除文章 '+d.title" @click="remove(d)"><Trash2 :size="16"/></button><NuxtLink :to="'/documents/'+d.id" class="icon-button" :aria-label="'打开文章 '+d.title"><ArrowUpRight :size="20"/></NuxtLink></article></div><footer class="page-footer"><span>纸上有章法，笔下有自己的声音。</span><small>每一篇都在本机妥善保存</small></footer><UiModal v-if="creating" title="开始一篇文章" @close="creating=false"><form class="form-stack" @submit.prevent="create"><label>文章名称<input v-model="title" placeholder="给这篇新稿一个名字" autofocus></label><label>从哪里开始<select v-model="templateId"><option value="">一张白纸</option><option v-for="t in templates" :key="t.id" :value="t.id">{{t.name}} · {{t.data.blocks?.length}}枚组件</option></select></label><div class="modal-actions"><button class="btn primary">打开编排台</button></div></form></UiModal></div></template>
